msg.method = 'GET';
msg.url = 'https://unesaroombooking.mekansm.co.id/api/integration/v1/automation/commands';
msg.headers = { 'X-API-Key': env.get('SRS_PULL_KEY') };
return msg;

if (msg.statusCode !== 200) { node.warn('SRS status ' + msg.statusCode); return null; }
const cmds = (msg.payload && msg.payload.data && msg.payload.data.commands) || [];
return [cmds.map(c => ({ payload: c }))];

const c = msg.payload;
const now = Date.now();
// 1) hanya jalankan di dalam jendela berlaku
if (now < Date.parse(c.validFrom) || now >= Date.parse(c.expiresAt)) { node.warn('lewati ' + c.commandId + ' (di luar masa berlaku)'); return null; }
// 2) jangan jalankan perintah yang sama dua kali dalam 60 detik
const busy = flow.get('busy') || {};
if ((busy[c.commandId] || 0) > now) return null;
busy[c.commandId] = now + 60000;
flow.set('busy', busy);
// 3) payload untuk subflow kontrol (sama dengan payload adapter)
msg.command = c;
msg.payload = { roomCode: c.roomCode, classKey: c.classKey, action: c.action, eventId: c.eventId, bookingId: c.bookingId, source: c.source };
return msg;

// Datang dari subflow kontrol: msg.command = perintah asli; msg.ack = { success, devices:{ac,lamp,door}, message }
const id = msg.command.commandId;
const ack = msg.ack || { success: false, message: 'tidak ada hasil kontrol' };
msg.method = 'POST';
msg.url = 'https://unesaroombooking.mekansm.co.id/api/integration/v1/automation/commands/' + encodeURIComponent(id) + '/ack';
msg.headers = { 'X-API-Key': env.get('SRS_PULL_KEY'), 'Content-Type': 'application/json' };
msg.payload = { success: !!ack.success, devices: ack.devices || {}, message: ack.message || '' };
return msg;
